using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable]public sealed class ChallengeTargetWire{public string id;public NumberData target;}
 [Serializable]public sealed class ChallengeCatalogWire{public string id;public int stage,chapter,labs,classLimit,networkLimit,links;public double priceFactor,dataFactor;public bool alternate;public NumberData minimumINT;public ChallengeTargetWire[] goals;}
 [Serializable]public sealed class ChallengeCase{public string name,action,id,runId;public string[] items,links;public int stage;public double at,offlineLimit;public bool ready,entryAllowed,hasItems,hasLinks;public NumberData hardwarePrice;public StateData before,expected;public PrestigeMetrics rates;}
 [Serializable]public sealed class ChallengeCases{public string scope;public ChallengeCatalogWire[] catalog;public ChallengeCase[] cases;}
 public sealed class ChallengeParityTests
 {
  static void Near(ScientificNumber n,NumberData data,string name){var e=ScientificNumber.FromData(data);if(e.IsZero)Assert.That(n.IsZero,Is.True,name);else Assert.That(n.Log10(),Is.EqualTo(e.Log10()).Within(2e-10),name);}
  public static void Session(GameState n,GameState e,string name)
  {
   Assert.That(n.Challenges.Progress.stages,Is.EqualTo(e.Challenges.Progress.stages),name+" stages");Assert.That(n.Challenges.Progress.stars,Is.EqualTo(e.Challenges.Progress.stars),name+" stars");Assert.That(n.Challenges.Progress.completions,Is.EqualTo(e.Challenges.Progress.completions),name+" completions");Assert.That(n.Challenges.Progress.bestSeconds,Is.EqualTo(e.Challenges.Progress.bestSeconds).Within(1e-7),name+" best time");Assert.That(n.Challenges.Progress.unlocks,Is.EquivalentTo(e.Challenges.Progress.unlocks),name+" shared unlocks");Assert.That(n.Challenges.Progress.lastReturnId,Is.EqualTo(e.Challenges.Progress.lastReturnId),name+" return receipt");Assert.That(n.Challenges.Progress.lastSuccess,Is.EqualTo(e.Challenges.Progress.lastSuccess),name+" outcome");Assert.That(n.Challenges.Run?.id,Is.EqualTo(e.Challenges.Run?.id),name+" run");if(!ChallengeRules.Active(e))return;
   Assert.That(n.Challenges.Run.runId,Is.EqualTo(e.Challenges.Run.runId),name+" run ID");Assert.That(n.Challenges.Run.stage,Is.EqualTo(e.Challenges.Run.stage),name+" stage");Assert.That(n.Challenges.Run.networkLinks,Is.EqualTo(e.Challenges.Run.networkLinks),name+" selected links");var a=n.Challenges.Run.metrics;var b=e.Challenges.Run.metrics;Near(ScientificNumber.FromData(a.credits),b.credits,name+" produced credits");Near(ScientificNumber.FromData(a.data),b.data,name+" produced data");Assert.That(ScientificNumber.FromData(a.minimumINT).CompareTo(ScientificNumber.FromData(b.minimumINT)),Is.Zero,name+" exact minimum INT");Assert.That(ScientificNumber.FromData(a.researchData).CompareTo(ScientificNumber.FromData(b.researchData)),Is.Zero,name+" exact paid research data");Assert.That(new[]{a.prestiges,a.hardwarePurchases,a.milestones,a.training,a.research,a.quality,a.efficiency},Is.EqualTo(new[]{b.prestiges,b.hardwarePurchases,b.milestones,b.training,b.research,b.quality,b.efficiency}),name+" exact counters");Assert.That(a.researchAreas,Is.EqualTo(b.researchAreas),name+" completion areas");Assert.That(a.craftedIds,Is.EqualTo(b.craftedIds),name+" local IDs");Assert.That(a.craftedTypes,Is.EqualTo(b.craftedTypes),name+" crafted types");Assert.That(a.craftRarity,Is.EqualTo(b.craftRarity),name+" rarity");Assert.That(JsonUtility.ToJson(MainStateData.FromMain(n.Challenges.Main)),Is.EqualTo(JsonUtility.ToJson(MainStateData.FromMain(e.Challenges.Main))),name+" isolated paused main snapshot");
  }
  [Test]public void EveryCurrentStageHasExactSourceTargetsAndRules()
  {var f=JsonUtility.FromJson<ChallengeCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ChallengeReferenceCases.json")));Assert.That(f.catalog.Length,Is.EqualTo(690));Assert.That(ChallengeBalance.Stages.Length,Is.EqualTo(690));foreach(var q in f.catalog){var d=ChallengeRules.Definition(q.id,q.stage);Assert.That(d.Chapter,Is.EqualTo(q.chapter));Assert.That(d.Labs,Is.EqualTo(q.labs));Assert.That(d.ClassLimit,Is.EqualTo(q.classLimit));Assert.That(d.NetworkLimit,Is.EqualTo(q.networkLimit));Assert.That(d.Links,Is.EqualTo(q.links));Assert.That(d.PriceFactor,Is.EqualTo(q.priceFactor));Assert.That(d.DataFactor,Is.EqualTo(q.dataFactor));Assert.That(d.Alternate,Is.EqualTo(q.alternate));Assert.That(d.MinimumINT.CompareTo(ScientificNumber.FromData(q.minimumINT)),Is.Zero,q.id+q.stage+" minimum exact");Assert.That(d.Goals.Select(g=>g.Id),Is.EqualTo(q.goals.Select(g=>g.id)));for(int i=0;i<d.Goals.Length;i++)Assert.That(d.Goals[i].Target.CompareTo(ScientificNumber.FromData(q.goals[i].target)),Is.Zero,q.id+q.stage+" exact "+q.goals[i].id);}}
  [Test]public void CurrentTransactionsIsolationAndRewardsMatchActualTypeScript()
  {var f=JsonUtility.FromJson<ChallengeCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ChallengeReferenceCases.json")));Assert.That(f.cases.Length,Is.GreaterThan(350));foreach(var c in f.cases){var s=c.before.ToState();string before=JsonUtility.ToJson(StateData.From(s));var n=s;if(c.action=="hardware")Near(Game.HardwareCost(s,Array.FindIndex(Balance.Hardware,h=>h.Id==c.id),c.stage),c.hardwarePrice,c.name+" actual hardware price");switch(c.action){case "start":n=ChallengeRules.Start(s,c.id,c.stage,c.runId,c.hasItems?c.items:null,c.hasLinks?c.links:null);break;case "abort":n=ChallengeRules.Return(s,false);break;case "complete":n=ChallengeRules.Return(s,true);break;case "advance":n=Game.Advance(s,c.at);break;case "tap":n=Game.Tap(s,s.SavedAt);break;case "hardware":n=Game.Buy(s,c.id,c.stage);break;case "train":n=Game.Train(s,c.id);break;case "research":n=Game.Research(s,c.id);break;case "reset":n=PrestigeRules.Reset(s);break;case "axiom-reset":n=MetaRules.AxiomReset(s);break;case "node":n=PrestigeRules.Buy(s,c.id);break;case "axiom":n=MetaRules.Buy(s,c.id);break;case "develop":n=MetaRules.Develop(s);break;case "model-select":n=MetaRules.Select(s,c.id);break;case "model-upgrade":n=MetaRules.Upgrade(s,c.id);break;case "craft":n=Workshop.Craft(s,c.id);break;case "salvage":n=MetaAutomation.Salvage(s,c.id,.999999);break;}
   Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(before),c.name+" pure");PrestigeParityTests.Numbers(n,c.expected,c.name);var e=c.expected.ToState();Session(n,e,c.name);Assert.That(n.Meta.models,Is.EqualTo(e.Meta.models),c.name+" models");Assert.That(n.Workshop.activeModel,Is.EqualTo(e.Workshop.activeModel),c.name+" active model");Assert.That(n.Meta.rng,Is.EqualTo(e.Meta.rng),c.name+" model RNG");Assert.That(n.Workshop.inventory.Select(i=>i.challengeCopy),Is.EqualTo(e.Workshop.inventory.Select(i=>i.challengeCopy)),c.name+" immutable loadout copies");Assert.That(n.Workshop.researchFragments,Is.EqualTo(e.Workshop.researchFragments),c.name+" fragments");Near(Game.Compute(n),c.rates.compute,c.name+" compute");Near(Game.Income(n),c.rates.income,c.name+" income");Near(Game.DataRate(n),c.rates.dataRate,c.name+" data");Near(PrestigeRules.Claim(n),c.rates.claim,c.name+" claim");Assert.That(Game.WorkSpeed(n),Is.EqualTo(c.rates.trainingSpeed).Within(1e-7),c.name+" training");Assert.That(Game.WorkSpeed(n,true),Is.EqualTo(c.rates.researchSpeed).Within(1e-7),c.name+" research");Assert.That(Game.OfflineLimit(n),Is.EqualTo(c.offlineLimit).Within(1e-7),c.name+" offline budget");Assert.That(ChallengeRules.Ready(n),Is.EqualTo(c.ready),c.name+" completion proof");Game.Validate(n);
  }}
 }
}
